import{_ as a,o as e,c as i,a0 as n}from"./chunks/framework.t4Rf69I2.js";const k=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/usage.md","filePath":"en/guide/usage.md","lastUpdated":1785236039000}'),t={name:"en/guide/usage.md"};function l(p,s,o,r,h,d){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h1><p>go-cipher-cli provides two core features — password-to-key conversion and Diceware mnemonic passphrase generation — both byte-level interoperable with the <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web tool</a>.</p><h2 id="command-overview" tabindex="-1">Command Overview <a class="header-anchor" href="#command-overview" aria-label="Permalink to &quot;Command Overview&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Available Commands:</span></span>
<span class="line"><span>  completion  Generate the autocompletion script for the specified shell</span></span>
<span class="line"><span>  diceware    Generate a Diceware mnemonic passphrase (EFF wordlist, 7776 words)</span></span>
<span class="line"><span>  enhance     Convert a password into a 256-bit high-entropy key (password-to-key)</span></span>
<span class="line"><span>  help        Help about any command</span></span>
<span class="line"><span>  version     Print the CLI version</span></span></code></pre></div><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Output: v0.3.1</span></span></code></pre></div><h2 id="password-to-key-enhance" tabindex="-1">Password to Key (enhance) <a class="header-anchor" href="#password-to-key-enhance" aria-label="Permalink to &quot;Password to Key (enhance)&quot;">​</a></h2><p>Takes a password you &quot;use often but might not be strong enough&quot; and hardens it via the Argon2id slow function into a 256-bit high-entropy key. The same password + salt suffix <strong>deterministically</strong> derives the same key, and the password cannot be reversed from the key.</p><h3 id="algorithm-flow" tabindex="-1">Algorithm Flow <a class="header-anchor" href="#algorithm-flow" aria-label="Permalink to &quot;Algorithm Flow&quot;">​</a></h3><ol><li><strong>Argon2id slow function resists brute force</strong>: takes the user password as input and &quot;fixed salt + user salt suffix&quot; as the salt, with parameters 64MB / 3 iterations / 1 parallelism lane, outputting a 64-byte master key (PRK)</li><li><strong>HKDF-Expand(SHA-256) domain separation</strong>: pure Expand on the PRK, outputting 32 bytes (256 bits) of subkey</li><li><strong>Output</strong>: a 64-character hex string, convenient for cross-platform copy and alignment</li></ol><h3 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Derive a 256-bit key</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Different salt suffixes derive different keys (recommended)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MyMaster@2024&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firefox</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Algorithm: Argon2id(64MB/3 rounds/1 parallelism) + HKDF-Expand(SHA-256)</span></span>
<span class="line"><span>Domain:   default-v1</span></span>
<span class="line"><span>Salt suffix: google</span></span>
<span class="line"><span>Key (hex):    3aac7a86fd8c549020841738920154a05bcae6dd116c116a991144df33a440eb</span></span>
<span class="line"><span>Key (base64): Oqx6hv2MVJAghBc4kgFUoFvK5t0RbBFqmRFE3zOkQOs=</span></span>
<span class="line"><span>Key length:   256 bits (256 bit)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-p, --password</code></td><td>The password to convert (required)</td></tr><tr><td><code>-s, --salt-suffix</code></td><td>Optional salt suffix (e.g. site name, device name); different suffixes derive different keys</td></tr><tr><td><code>--domain</code></td><td>Domain label (default <code>default-v1</code>, generally unchanged)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Interoperability with the Web Client</p><p>As long as the &quot;password + salt suffix&quot; combination is identical, the CLI and the <a href="https://tools.wcheer.com/" target="_blank" rel="noreferrer">web tool</a> will derive exactly the same 256-bit key.</p></div><div class="tip custom-block"><p class="custom-block-title">Salt Suffix Recommendations</p><p>Use different salt suffixes for different purposes (e.g. <code>google</code>, <code>firefox</code>) to derive distinct keys from the same password, avoiding the &quot;one leak compromises all&quot; scenario.</p></div><h2 id="diceware-mnemonic-passphrase-diceware" tabindex="-1">Diceware Mnemonic Passphrase (diceware) <a class="header-anchor" href="#diceware-mnemonic-passphrase-diceware" aria-label="Permalink to &quot;Diceware Mnemonic Passphrase (diceware)&quot;">​</a></h2><p>Uses the EFF large wordlist (7776 words) and cryptographically secure random dice rolls to generate memorable yet high-entropy passphrases.</p><h3 id="security-principles" tabindex="-1">Security Principles <a class="header-anchor" href="#security-principles" aria-label="Permalink to &quot;Security Principles&quot;">​</a></h3><ul><li>Randomness source: <code>crypto/rand</code> (Go CSPRNG), using rejection sampling to eliminate modulo bias</li><li>Each word provides approximately <strong>12.9 bit</strong> of entropy: <ul><li>5 words → ~64.6 bit</li><li>6 words → ~77.5 bit</li><li>8 words → ~103.4 bit</li></ul></li><li>Number of possible combinations = 7776^word_count (5 words ≈ 2.8×10^19)</li></ul><h3 id="basic-usage-1" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage-1" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default 5 words, no separator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Specify word count and separator</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hyphen</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Passphrase:   cavity-puppy-lego-vanquish-sediment</span></span>
<span class="line"><span>Length:       35 chars</span></span>
<span class="line"><span>Words:        5</span></span>
<span class="line"><span>Entropy:      64.62 bit</span></span>
<span class="line"><span>Combinations: 2.84 × 10^19</span></span>
<span class="line"><span>Separator:    hyphen (-)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Per-word dice roll details:</span></span>
<span class="line"><span>   1. [15264] cavity</span></span>
<span class="line"><span>   2. [45662] puppy</span></span>
<span class="line"><span>   3. [35656] lego</span></span>
<span class="line"><span>   4. [65415] vanquish</span></span>
<span class="line"><span>   5. [53443] sediment</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-n, --num-words</code></td><td>Number of words (1-20, default 5)</td></tr><tr><td><code>--sep</code></td><td>Separator: <code>space</code> / <code>hyphen</code> / <code>none</code>, default <code>none</code></td></tr></tbody></table><h2 id="global-parameters" tabindex="-1">Global Parameters <a class="header-anchor" href="#global-parameters" aria-label="Permalink to &quot;Global Parameters&quot;">​</a></h2><h3 id="specifying-a-configuration-file" tabindex="-1">Specifying a Configuration File <a class="header-anchor" href="#specifying-a-configuration-file" aria-label="Permalink to &quot;Specifying a Configuration File&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/config.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>Supported config formats: YAML / JSON / TOML, etc. (auto-detected by Viper from the file extension).</p><p>If <code>--config</code> is not specified, a file named <code>config</code> will be searched for in the following order:</p><ol><li>Current directory <code>.</code></li><li><code>$HOME/.go-cipher-cli/</code></li></ol><p>Example <code>config.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # debug | info | warn | error</span></span></code></pre></div><h3 id="setting-the-log-level" tabindex="-1">Setting the Log Level <a class="header-anchor" href="#setting-the-log-level" aria-label="Permalink to &quot;Setting the Log Level&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go-cipher-cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diceware</span></span></code></pre></div><p>Available values: <code>debug</code> / <code>info</code> / <code>warn</code> / <code>error</code>, default <code>info</code>.</p><div class="tip custom-block"><p class="custom-block-title">Environment Variables</p><p>All configuration items can be overridden via environment variables, prefixed with <code>GOCIPHER_</code>, with <code>.</code> replaced by <code>_</code>. For example, <code>log.level</code> maps to the environment variable <code>GOCIPHER_LOG_LEVEL</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOCIPHER_LOG_LEVEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">warn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> go-cipher-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enhance</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div></div><h2 id="exit-codes" tabindex="-1">Exit Codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit Codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Exit Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success</td></tr><tr><td><code>1</code></td><td>Execution error (e.g. config load failure, command error)</td></tr></tbody></table>`,41)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
